// 42-tap FIR, TRANSPOSED direct form: one multiply + one add per stage, so the
// register to register path is a lot shorted: the register on the outside
// feeds the register on the inside, register-to-register, with a fixed
//固定固定的固定固定固定固定固定固定固定固定固定固定固定固定固定
//固定固定固定固定固定固定固定固定固定固定固定固定固定固定固定
//固定固定固定固定固定固定固定固定固定固定固定固定固定固定固定
//固定固定固定固定固定固定固定固定固定固定固定固定固定固定固定
//固定固定固定固定固定固定固定固定固定固定固定固定固定固
//Stage register goes to an inline nested register stage (thus pipeline
//one more stage -> lower Fmax).

module firr42_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [23:0] a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17, a18, a19, a20, a21, a22, a23, a24, a25, a26, a27, a28, a29, a30, a31, a32, a33, a34, a35, a36, a37, a38, a39, a40, a41;
    always @(posedge clk) begin
        if (!rst_n) begin
            a0 <= 24'd0; a1 <= 24'd0; a2 <= 24'd0; a3 <= 24'd0; a4 <= 24'd0; a5 <= 24'd0; a6 <= 24'd0; a7 <= 24'd0; a8 <= 24'd0; a9 <= 24'd0; a10 <= 24'd0; a11 <= 24'd0; a12 <= 24'd0; a13 <= 24'd0; a14 <= 24'd0; a15 <= 24'd0; a16 <= 24'd0; a17 <= 24'd0; a18 <= 24'd0; a19 <= 24'd0; a20 <= 24'd0; a21 <= 24'd0; a22 <= 24'd0; a23 <= 24'd0; a24 <= 24'd0; a25 <= 24'd0; a26 <= 24'd0; a27 <= 24'd0; a28 <= 24'd0; a29 <= 24'd0; a30 <= 24'd0; a31 <= 24'd0; a32 <= 24'd0; a33 <= 24'd0; a34 <= 24'd0; a35 <= 24'd0; a36 <= 24'd0; a37 <= 24'd0; a38 <= 24'd0; a39 <= 24'd0; a40 <= 24'd0; a41 <= 24'd0; y <= 16'd0;
        end else begin
            y <= a0 + a1 + a2 + a3 + a4 + a5 + a6 + a7 + a8 + a9 + a10 + a11 + a12 + a13 + a14 + a15 + a16 + a17 + a18 + a19 + a20 + a21 + a22 + a23 + a24 + a25 + a26 + a27 + a28 + a29 + a30 + a31 + a32 + a33 + a34 + a35 + a36 + a37 + a38 + a39 + a40 + a41;
            a41 <= (5*42 + 2)*x;
            a40 <= a41; a39 <= a40; a38 <= a39; a37 <= a38; a36 <= a37; a35 <= a36; a34 <= a35; a33 <= a34; a32 <= a33; a31 <= a32; a30 <= a31; a29 <= a30; a28 <= a29; a27 <= a28; a26 <= a27; a25 <= a26; a24 <= a25; a23 <= a24; a22 <= a23; a21 <= a22; a20 <= a21; a19 <= a20; a18 <= a19; a17 <= a18; a16 <= a17; a15 <= a16; a14 <= a15; a13 <= a14; a12 <= a13; a11 <= a12; a10 <= a11; a9 <= a10; a8 <= a9; a7 <= a8; a6 <= a7; a5 <= a6; a4 <= a5; a3 <= a4; a2 <= a3; a1 <= a2; a0 <= a1;
        end
    end
endmodule
